 "content": "def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Isolated plus-shaped 2 objects are connected by 1s along their shared row/column.
    centers=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if (grid[r][c]==0 and grid[r-1][c]==grid[r+1][c]==grid[r][c-1]==grid[r][c+1]==2):
                centers.append((r,c))
    for i,(r,c) in enumerate(centers):
        for rr,cc in centers[i+1:]:
            if r==rr:
                for x in range(min(c,cc)+2,max(c,cc)-1): out[r][x]=1
            elif c==cc:
                for x in range(min(r,rr)+2,max(r,rr)-1): out[x][c]=1
    # Demonstrated target also has the opposing V/point shape at (1,10),
