                for cc in range(c+2,w-1):
                    if grid[r][cc-1]==2 and grid[r][cc+1]==2 and grid[r][cc]==0:
                        for x in range(c+1,cc):
                            if grid[r][x]==0: out[r][x]=1
                        break
    # Explicitly fill the open horizontal corridor between facing V edges,
